import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第96章 橙子","description":"","frontmatter":{},"headers":[],"relativePath":"第96章_橙子.md","filePath":"第96章_橙子.md"}'),_={name:"第96章_橙子.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第96章-橙子" tabindex="-1">第96章 橙子 <a class="header-anchor" href="#第96章-橙子" aria-label="Permalink to &quot;第96章 橙子&quot;">​</a></h1><p>第二年九月，她回来了。</p><p>落地那天她在旧号上发了一张照片：一箱橙子，堆在超市免费架旁边，纸箱开了一个口子，露出三层。</p><p>配的字是四个字——我落地了。</p><p>我知道这四个字的分量。她上一次在旧号上发&quot;我落地了&quot;，后面还跟着半句&quot;一切都好，放心&quot;。那半句是写给她妈拿去发到亲戚群里的。</p><p>这一次没有放心。</p><p>那天下午我在实验室，手上是一副手套，橡胶的，里面全是汗。我把它脱了才回她，问她现在人在哪儿。</p><p>机场外面等车。今天直接回家。</p><p>我说你不先讲一声。</p><p>发出去我就后悔了。这句话听起来像质问，而我问的不是这个。我要问的是她为什么要一个人回那座城，而不是先到我这边的车站。</p><p>她隔了很久。久到我以为她上了车。</p><p>她说，我讲了你要来。</p><p>我说我要来。</p><p>她说，我知道。所以我不讲。</p><p>那天夜里十一点，她连上她们小区楼下那个很差的公共信号，给我打了一长段。</p><p>她说她在飞机上睡了三小时。说她在自家阳台上站了一会儿，栏杆换了，换成铁的，她不喜欢。说她妈在厨房里煮东西，她进门的时候她妈没回头，只讲了一句&quot;鞋在底下&quot;。</p><p>她说，我这一辈子听到的最难受的一句欢迎，就是鞋在底下。</p><p>我在这边把台灯拧暗了一格。</p><p>我说那你当时怎么样。</p><p>她说她&quot;哦&quot;了一声，进了自己那间屋。那间屋还给她留着，里面放的是她妹的东西，那些东西今天全搬走了。她说她坐在那张床上，床上有一块圆形的印子，是她妹那把转椅常年压出来的。</p><p>她说她在那个印子上坐了一个钟头。</p><p>我说你现在在哪儿。</p><p>她说在楼下，坐在那把公共椅子上，连的是隔壁店的网。她说她不能在那个屋里跟我讲话，她妈十二点要上楼关门。</p><p>她明天要去办一件事。她把学籍上那个东西彻底转走，回这边重新进一个。一个美院的进修班，读两年。</p><p>我说两年以后呢。</p><p>她说两年以后她不一定读得出。</p><p>我把这句话抄在纸上才敢往下看。我问她那两年的钱。她说三万那笔够一年，剩下的一年她接活。我说你又要一天打两份。她说她这辈子就是这样，让我别用那种语气。</p><p>她说这次是她自己选的。</p><p>她说她妈替她挑的那一条，钱是一样的，累也是一样的，只有名字不一样。</p><p>她说，名字一样以后，我不恨了。</p><p>那我问她恨谁。</p><p>她说谁也不恨。她说她落地以后在飞机上想明白一件事：她这一辈子一直恨着一个人，是她自己。因为她这一年拿了两万八的展费、三万的卡、一个铁盒、一张写着&quot;未参加&quot;的回执，她全部收下了，然后每天晚上跟自己讲一遍&quot;我不配&quot;。</p><p>她说她今天在阳台上想，如果她把这笔账整个认下来，她就不用再恨自己。</p><p>她说她认了。</p><p>她说认完她在阳台上又站了一会儿，她妈在楼下喊吃饭，她下去吃了两碗。</p><p>我说那挺好。</p><p>她说你又&quot;那挺好&quot;。她说我要是想不出别的，我就讲我今天。</p><p>我说我今天在实验室弄到十一点，因为我在算她那边下午三点是不是在路上。</p><p>这句话我说出来才听见自己多丑。我在那间屋子里对着一台离心机站到十一点，为的是把一个下午三点算成一个不能讲话的时间。</p><p>她那边安静了一会儿。楼下应该有风，我听见她那边有一串很细的杂音，是她那个信号不好的老毛病。</p><p>她说，我现在跟你一个小时也不差。</p><p>她说她知道这句话听起来不像好事。她说她这几年每天拿着一张表，算他那边几点，几点能讲，讲了以后她要几点睡。她说今天早上她从到达厅里出来，拿手机看了一眼，六点。她那边六点，他那边也六点。</p><p>她说她站在那儿愣了很久。</p><p>她说她把那张表丢了，然后发现她不知道该在几点跟人讲话。</p><p>我说那你什么时候想讲就讲。</p><p>她说她不行。她说她以前可以不算，因为不算也没用，反正人不在。现在她在这个城里，她一不算，就要开始想她要不要出去。</p><p>我伸手把台灯拧灭了。黑的屋子里我看手机更清楚一点。这是我今年第二次拿手去弄那个灯。</p><p>她说，我们两个这一辈子第一次没有时差。她说她以为没有时差就好了。她说她今天发现，没有时差只是把一件事换了个名字。</p><p>我问什么名字。</p><p>她说以前他们隔的是钟点。现在隔的是那一屋子里能随手拿起她手机的人。</p><p>还有她妈今天晚上问她明天想吃什么。她说她妈讲这句话的时候，心里算的是她明天能不能起得晚一点。</p><p>我坐在那儿没动。</p><p>我算了三年&quot;我这边的十二点是她那边的七点&quot;。现在这张表没有用了。我手里只剩一个事实：我十一点，她也十一点。</p><p>我说那我早上七点起来，你那边也七点。</p><p>她说对。</p><p>我说那我早上找你，你不在。</p><p>她说你以前也不在。她只是以前不在得那么远。</p><p>那晚她十一点半下线。下线之前她说了一句别的。</p><p>她说我明年不要报宁城了。</p><p>我说我不报了。</p><p>她问我去哪儿。</p><p>我说我留在这儿。</p><p>她说好。她说那我们现在隔一个公交。</p><p>我说，一个公交能过完一辈子吗。</p><p>她说她不知道。她说他这輩子第一次问这种问题。</p><p>我说因为我今年手里什么都没有，我只能问这个。</p><p>她隔了很久才回。</p><p>她说，你手里有一本本子，还有一个箱子。她说你别把这两样当零。</p><p>她挂了。</p><p>那天夜里我把那个箱子从床底下拖出来。</p><p>胶带我拆了很久。屋里的灯是那种很白的日光灯，我把东西一件一件摆到桌上。</p><p>她的三十多件周边。两个娃娃。一袋小卡。阿婆那个铁盒。我的本子。我算&quot;以后&quot;的那张纸，二百九十三道杠。一片从旧画册上掉下来的纸屑。还有一张回执，上面写着&quot;该生于本年度未被录取&quot;。</p><p>我一样一样看了一遍。</p><p>看到那个铁盒的时候我拿起来贴到耳朵边上晃了一下。里面有很轻的一声响，是很多小东西碰在一起。我答应过她我不开，我还是没开。</p><p>看完我全部放回去。</p><p>我封了两道胶带，把它推回床底。</p><p>我那天夜里第一次觉得：这个屋子里最像我的地方，是一个不属于我的箱子。</p>',77)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
